-- SISA PERUBAHAN YANG BELUM TERPASANG (jalankan di Supabase SQL Editor, urut dari atas).
-- Sudah terpasang: 38 video dipindah ke kode lama; 172 latihan baru terisi (nama Inggris, isi Indonesia); nama Inggris untuk latihan lama.
-- Koneksi otomatis menggantung pada perintah DELETE dan pada UPDATE how_to kode lama, jadi bagian ini perlu dijalankan manual.

-- 1) Pertukaran video salah: CX01 dan CX04 memegang video yang tidak sesuai nama; videonya ada di CT01 dan SL01.
delete from public.exercise_video_assets where exercise_id in ('CX01','CX04');
update public.exercise_video_assets set exercise_id='CX01' where exercise_id='CT01';
update public.exercise_video_assets set exercise_id='CX04' where exercise_id='SL01';

-- 2) Pastikan 41 kode ini tidak dipakai (harus semua 0), lalu hapus.
select (select count(*) from public.diagnosis_exercise_plans d where d.phase1 && array['AC01','AG01','AH01','AJ01','AQ01','AT01','AU01','AZ01','BG01','BR01','BS01','BV01','BY01','CA01','CD01','CF01','CP01','CR01','CT01','CU01','DB01','DC01','DK01','DN01','GE01','HA01','HD01','KC01','PE01','PV01','PY01','PZ01','QS01','RE01','RM01','RN01','RR01','SB01','SL01','ST01','IR01']::text[] or d.phase2 && array['AC01','AG01','AH01','AJ01','AQ01','AT01','AU01','AZ01','BG01','BR01','BS01','BV01','BY01','CA01','CD01','CF01','CP01','CR01','CT01','CU01','DB01','DC01','DK01','DN01','GE01','HA01','HD01','KC01','PE01','PV01','PY01','PZ01','QS01','RE01','RM01','RN01','RR01','SB01','SL01','ST01','IR01']::text[] or d.phase3 && array['AC01','AG01','AH01','AJ01','AQ01','AT01','AU01','AZ01','BG01','BR01','BS01','BV01','BY01','CA01','CD01','CF01','CP01','CR01','CT01','CU01','DB01','DC01','DK01','DN01','GE01','HA01','HD01','KC01','PE01','PV01','PY01','PZ01','QS01','RE01','RM01','RN01','RR01','SB01','SL01','ST01','IR01']::text[]) as rencana_diagnosa,
       (select count(*) from public.medical_records m where jsonb_typeof(m.plan_data->'exercises')='object' and (m.plan_data->'exercises') ?| array['AC01','AG01','AH01','AJ01','AQ01','AT01','AU01','AZ01','BG01','BR01','BS01','BV01','BY01','CA01','CD01','CF01','CP01','CR01','CT01','CU01','DB01','DC01','DK01','DN01','GE01','HA01','HD01','KC01','PE01','PV01','PY01','PZ01','QS01','RE01','RM01','RN01','RR01','SB01','SL01','ST01','IR01']::text[]) as soap,
       (select count(*) from public.patient_exercise_logs where exercise_id = any(array['AC01','AG01','AH01','AJ01','AQ01','AT01','AU01','AZ01','BG01','BR01','BS01','BV01','BY01','CA01','CD01','CF01','CP01','CR01','CT01','CU01','DB01','DC01','DK01','DN01','GE01','HA01','HD01','KC01','PE01','PV01','PY01','PZ01','QS01','RE01','RM01','RN01','RR01','SB01','SL01','ST01','IR01']::text[])) as log_pasien,
       (select count(*) from public.exercise_video_assets where exercise_id = any(array['AC01','AG01','AH01','AJ01','AQ01','AT01','AU01','AZ01','BG01','BR01','BS01','BV01','BY01','CA01','CD01','CF01','CP01','CR01','CT01','CU01','DB01','DC01','DK01','DN01','GE01','HA01','HD01','KC01','PE01','PV01','PY01','PZ01','QS01','RE01','RM01','RN01','RR01','SB01','SL01','ST01','IR01']::text[])) as video_tersisa;
delete from public.plan_exercises where id = any(array['AC01','AG01','AH01','AJ01','AQ01','AT01','AU01','AZ01','BG01','BR01','BS01','BV01','BY01','CA01','CD01','CF01','CP01','CR01','CT01','CU01','DB01','DC01','DK01','DN01','GE01','HA01','HD01','KC01','PE01','PV01','PY01','PZ01','QS01','RE01','RM01','RN01','RR01','SB01','SL01','ST01','IR01']::text[]);

-- 3) Cara melakukan (Indonesia) untuk 14 kode lama yang menerima video.
update public.plan_exercises set how_to='Duduk selonjor bersandar pada kedua tangan. Angkat satu tungkai lurus sedikit dari lantai, lalu gerakkan pergelangan kaki naik-turun berulang; ganti sisi. Alternatif: tulis huruf A-Z dengan ujung kaki.' where id='AK01';
update public.plan_exercises set how_to='Berdiri menghadap kursi atau dinding, kedua tangan bertumpu pada sandaran. Satu kaki melangkah lurus ke belakang dengan tumit tetap menapak, dorong badan ke depan sampai betis terasa teregang; ulangi dengan lutut belakang sedikit ditekuk untuk otot soleus.' where id='AK03';
update public.plan_exercises set how_to='Duduk di kursi, silangkan pergelangan satu kaki di atas lutut lain. Pegang jari kaki dan tarik ke arah tulang kering sampai terasa regang di telapak kaki; bisa juga memakai handuk.' where id='AK04';
update public.plan_exercises set how_to='Berdiri tegak berpegangan pada sandaran kursi. Naik ke ujung jari kaki dengan dua kaki, tahan sebentar, turun pelan; lanjutkan ke satu kaki bila mampu.' where id='AK06';
update public.plan_exercises set how_to='Berdiri satu kaki di atas papan goyang (wobble board) atau BOSU, lutut kaki lain diangkat; jaga keseimbangan tanpa menyentuhkan tepi papan ke lantai.' where id='AK11';
update public.plan_exercises set how_to='Berdiri satu kaki di atas permukaan tidak stabil (balance dome/BOSU, bantal, atau foam pad), lutut kaki lain diangkat; jaga keseimbangan.' where id='KN17';
update public.plan_exercises set how_to='Duduk tegak, letakkan satu tangan di belakang punggung. Miringkan kepala ke sisi berlawanan dari tangan di belakang punggung, lalu tarik ringan kepala dengan tangan lain ke arah samping sampai terasa regang di sisi leher. Tahan 20-30 detik sambil bernapas normal; bahu tidak terangkat.' where id='CX06';
update public.plan_exercises set how_to='Duduk, lengan bawah bertumpu di tepi meja. Remas bola tenis (atau putty) dengan seluruh jari, tahan, lalu lepaskan pelan.' where id='EW07';
update public.plan_exercises set how_to='Tengkurap, lengan lurus ke depan, leher netral. Angkat kedua lengan dan kedua tungkai sedikit dari lantai (atau mulai dari dada dan lengan saja bila belum kuat), tahan, turun pelan.' where id='LB13';
update public.plan_exercises set how_to='Duduk bersandar pada kedua tangan (atau telentang, lutut ditekuk), letakkan bola di antara kedua lutut. Remas bola dengan kontrol, tahan, lepaskan.' where id='HP09';
update public.plan_exercises set how_to='Telentang, satu lutut ditekuk dengan telapak menapak, tungkai lain lurus. Kencangkan paha, angkat tungkai lurus sekitar 30-60 cm (boleh lebih tinggi bila nyaman), turunkan pelan. Ganti sisi.' where id='HP17';
update public.plan_exercises set how_to='Duduk selonjor bersandar pada kedua tangan, foam roller atau gulungan handuk di bawah lutut. Kencangkan paha menekan lutut ke roller, tahan; bila mampu luruskan lutut sehingga tumit terangkat (short arc), turunkan pelan.' where id='KN01';
update public.plan_exercises set how_to='Duduk tegak, satu tangan memegang kursi atau di samping badan. Letakkan tangan lain di atas kepala dan miringkan kepala ke sisi tersebut dengan tarikan ringan sampai terasa regang di sisi leher. Tahan, lalu ganti sisi.' where id='CX04';
update public.plan_exercises set how_to='Duduk tegak, tangan di paha. Tundukkan kepala pelan, tengadahkan, lalu miringkan telinga ke bahu kanan dan kiri bergantian dalam rentang tanpa nyeri.' where id='RM02';

-- 4) Verifikasi: harusnya 388 latihan dan 219 video.
select (select count(*) from public.plan_exercises) latihan, (select count(*) from public.exercise_video_assets) video;
